/* The interface between the X0X app (GPL-3.0-only) and a separate Bluetooth controller image
 * (ble/ctl, MPL-2.0 shim plus JieLi's own files, built by the user). This header is the only code
 * that both sides compile. It is MPL-2.0 so that the controller image can use it.
 *
 * The two sides are like two chips on one board:
 *   - the image sits in its own flash block (64 KiB, XIP 0x02087000) and owns its own RAM window;
 *   - the app starts it once on core 1 (init), then calls its idle entry (poll) from core 1's idle
 *     loop, and talks to it only through standard HCI packets (H4 types) in two byte rings.
 * Nothing else crosses: no app function is called by the image, no image function is called by
 * the app except init and poll.
 *
 * Ring frame: [u16 len, little endian][u8 H4 type][len - 1 bytes]. One writer and one reader per
 * ring. The writer fills the bytes, then XB_SYNC(), then moves head. The reader reads, then
 * XB_SYNC(), then moves tail. Define XB_SYNC before this header (the default is a compiler
 * barrier plus the host's full fence). */
#pragma once
#include <stdint.h>

#ifndef XB_SYNC
#define XB_SYNC() __sync_synchronize()
#endif

#define XB_HDR_MAGIC   0x43423058u        /* "X0BC": the image header */
#define XB_BOOT_MAGIC  0x50424C43u        /* "CLBP": the boot parameters */
#define XB_MBOX_MAGIC  0x584D4258u        /* "XBMX": the mailbox */
#define XB_ABI         2u                 /* this layout (header, boot parameters, mailbox) */
#define XB_HDR_VERSION 2u

/* where the image lives (SMK-37 flash layout 2) and the RAM it may own */
#define XB_FLASH_OFF   0x0008B000u        /* flash offset of the Bluetooth block */
#define XB_FLASH_XIP   0x02087000u        /* its XIP address (the image is linked here) */
#define XB_FLASH_SIZE  0x00010000u        /* 64 KiB */
#define XB_RAM_LO      0x01C01800u        /* the image's RAM window (after the app's RAM code) */
#define XB_RAM_HI      0x01C07F00u        /* (0x01C07F00.. is crt0's status words) */

/* the image header: the first bytes of the image. mkimage.py fills image_size and crc32. */
typedef struct {
    uint32_t magic;                       /* XB_HDR_MAGIC */
    uint16_t hdr_version, hdr_size;       /* XB_HDR_VERSION, sizeof(xb_header_t) */
    uint32_t fw_version;                  /* the image's own version (major << 16 | minor) */
    uint32_t image_size;                  /* bytes from the header to the end of the image */
    uint32_t crc32;                       /* CRC-32 (IEEE) of the image with this field 0 */
    uint32_t abi;                         /* XB_ABI */
    uint32_t init;                        /* int init(const xb_boot_t *): core 1, once; 0 = ready */
    uint32_t poll;                        /* void poll(void): core 1 idle loop, interrupts on */
    uint32_t isr_stack_lo, isr_stack_hi;  /* core 1's interrupt stack (its ssp) */
    uint32_t ram_lo, ram_hi;              /* all the RAM the image uses: inside XB_RAM_LO..HI */
    uint32_t irq_lo, irq_hi;              /* the interrupt numbers it may route to core 1 (bits) */
    uint32_t rsv[3];
} xb_header_t;

/* the boot parameters: the app fills them, the image reads them in init */
typedef struct {
    uint32_t magic;                       /* XB_BOOT_MAGIC */
    uint32_t abi;                         /* XB_ABI */
    uint32_t sys_clk_hz, lsb_clk_hz, hsb_clk_hz;
    uint32_t tick_addr;                   /* a free-running up-counter the image may read */
    uint32_t ticks_per_ms;
    uint32_t mbox;                        /* address of the xb_mbox_t */
    uint32_t settle_ms;                   /* how long init may run the controller before it returns */
    uint32_t vec_base;                    /* the interrupt vector table (128 words) */
    uint32_t icfg_base;                   /* core 1's interrupt configuration words (4 bits each) */
    uint8_t xosc[2];                      /* RF calibration: crystal trim left, right */
    uint8_t pa_trim[7];
    uint8_t osc_type;
    uint8_t mcs_dgain[20];
    uint8_t pwr_max, pwr_ble;             /* bt_max_pwr_set: the overall and the BLE level */
} xb_boot_t;

/* controller states (mbox.state, written by the image) */
enum { XB_ST_OFF = 0, XB_ST_INIT = 1, XB_ST_READY = 2, XB_ST_FAILED = 3 };
/* mbox.dbg: [XB_DBG_STAGE] the last init step it reached (XB_STG_*), [XB_DBG_MS] its own ms
 * then, [XB_DBG_DELAYS] delay_us calls (the RF trim makes most of them), [XB_DBG_RA] the caller of
 * the last delay_us (bit 0 set while that delay runs), [XB_DBG_INIT_MS] how long init ran,
 * [XB_DBG_STALL] bits 0-15: delays that saw the tick counter stop, bits 16-31: the caller's caller
 * of the last delay (low 16 bits of the address) */
enum { XB_DBG_STAGE = 0, XB_DBG_MS = 1, XB_DBG_DELAYS = 2, XB_DBG_RA = 3, XB_DBG_INIT_MS = 4, XB_DBG_STALL = 5 };
enum { XB_STG_ENTRY = 1, XB_STG_OS = 2, XB_STG_H4 = 3, XB_STG_TASK = 4, XB_STG_SETTLE = 5, XB_STG_SETTLED = 6,
       XB_STG_READY = 7 };
/* image errors (mbox.err) */
enum { XB_E_NONE = 0, XB_E_BOOT = 1, XB_E_HEAP = 2, XB_E_TASK = 3, XB_E_ASSERT = 4, XB_E_RESET = 5 };

#define XB_RING_SIZE 1024u                /* a power of two */
typedef struct {
    volatile uint32_t head;               /* the writer's (own cache line) */
    uint32_t pad0[7];
    volatile uint32_t tail;               /* the reader's (own cache line) */
    uint32_t pad1[7];
    uint8_t buf[XB_RING_SIZE];
} xb_ring_t;

typedef struct {
    uint32_t magic, abi;                  /* the app: XB_MBOX_MAGIC, XB_ABI */
    volatile uint32_t dbg[6];             /* the image: its start record (XB_DBG_*), for diagnosis only.
                                           * The app sets them to 0 before init; the layout is ABI 2. */
    volatile uint32_t state, err;         /* the image: XB_ST_*, XB_E_* */
    volatile uint32_t c2h_drops;          /* the image: frames it could not put (ring full) */
    volatile uint32_t irqs_routed[4];     /* the image: the interrupt numbers it took (bits 0-127) */
    volatile uint32_t polls;              /* the image: poll calls (a heartbeat) */
    xb_ring_t h2c;                        /* app -> image: HCI commands and ACL data */
    xb_ring_t c2h;                        /* image -> app: HCI events and ACL data */
} xb_mbox_t;

#define XB_FRAME_MAX 300u                 /* the largest frame either side writes (type + payload) */

static inline uint32_t xb_ring_used(const xb_ring_t *r)
{
    return (r->head - r->tail) & (XB_RING_SIZE - 1u);
}
static inline uint32_t xb_ring_free(const xb_ring_t *r)
{
    return XB_RING_SIZE - 1u - xb_ring_used(r);
}

/* one frame in: 0 = written, -1 = no room (nothing written), -2 = bad length */
static inline int xb_frame_put(xb_ring_t *r, uint8_t type, const uint8_t *p, uint32_t n)
{
    uint32_t len = n + 1u, h, i;
    if (len > XB_FRAME_MAX)
        return -2;
    if (xb_ring_free(r) < len + 2u)
        return -1;
    h = r->head;
    r->buf[h] = (uint8_t)len;
    h = (h + 1u) & (XB_RING_SIZE - 1u);
    r->buf[h] = (uint8_t)(len >> 8);
    h = (h + 1u) & (XB_RING_SIZE - 1u);
    r->buf[h] = type;
    h = (h + 1u) & (XB_RING_SIZE - 1u);
    for (i = 0; i < n; i++) {
        r->buf[h] = p[i];
        h = (h + 1u) & (XB_RING_SIZE - 1u);
    }
    XB_SYNC();
    r->head = h;
    XB_SYNC();
    return 0;
}

/* the type of the next frame and its payload length: 1 = a whole frame waits, 0 = none,
 * -1 = the ring holds a bad length (the reader drops everything: xb_ring_flush) */
static inline int xb_frame_peek(const xb_ring_t *r, uint8_t *type, uint32_t *n)
{
    uint32_t used, t, len;
    XB_SYNC();
    used = xb_ring_used(r);
    if (used < 3u)
        return 0;
    t = r->tail;
    len = (uint32_t)r->buf[t] | (uint32_t)r->buf[(t + 1u) & (XB_RING_SIZE - 1u)] << 8;
    if (len == 0 || len > XB_FRAME_MAX)
        return -1;
    if (used < len + 2u)
        return 0;
    *type = r->buf[(t + 2u) & (XB_RING_SIZE - 1u)];
    *n = len - 1u;
    return 1;
}

/* one frame out into p (max bytes): the payload length, 0 = none, -1 = bad length or too long for
 * p (the frame is dropped, the ring stays in step) */
static inline int xb_frame_get(xb_ring_t *r, uint8_t *type, uint8_t *p, uint32_t max)
{
    uint32_t n = 0, t, i;
    int rc = xb_frame_peek(r, type, &n);
    if (rc <= 0) {
        if (rc < 0) {
            r->tail = r->head;            /* a bad length: nothing after it can be trusted */
            XB_SYNC();
        }
        return rc;
    }
    t = (r->tail + 3u) & (XB_RING_SIZE - 1u);
    for (i = 0; i < n; i++) {
        if (i < max)
            p[i] = r->buf[t];
        t = (t + 1u) & (XB_RING_SIZE - 1u);
    }
    XB_SYNC();
    r->tail = t;
    XB_SYNC();
    return n <= max ? (int)n : -1;
}

static inline void xb_ring_init(xb_ring_t *r)
{
    r->head = 0;
    r->tail = 0;
}

/* CRC-32 (IEEE, reflected 0xEDB88320), as zlib.crc32: the image check */
static inline uint32_t xb_crc32(uint32_t crc, const uint8_t *p, uint32_t n)
{
    uint32_t i, b;
    crc = ~crc;
    for (i = 0; i < n; i++) {
        crc ^= p[i];
        for (b = 0; b < 8u; b++)
            crc = (crc >> 1) ^ (0xEDB88320u & (0u - (crc & 1u)));
    }
    return ~crc;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* A driver's audio callback partition must not change BREAK's sample timeline.
 * Compare identical note/clock/tempo/bank events rendered in 1..256-frame chunks
 * against a single 256-frame callback. Compile with production breaks.c. */
#include <inttypes.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "firmware/src/dsp/breaks.h"

#define QUANTUM 256u
#define QUANTA 32u
#define NSAMPLES (QUANTUM * QUANTA)
static uint32_t rnd(uint32_t *p) { uint32_t s=*p; s^=s<<13; s^=s>>17; s^=s<<5; return *p=s; }
static void require(int ok, const char *reason)
{ if (!ok) { fprintf(stderr,"FAIL %s\n", reason); exit(1); } }
static uint64_t reached_live, reached_reverse, reached_bank, reached_stop;

/* Split each 256-sample event epoch differently. All inputs change ONLY at epoch boundaries. */
static const uint16_t partitions[5][6] = {
    {256,0,0,0,0,0}, {64,64,64,64,0,0}, {128,128,0,0,0,0},
    {1,7,13,31,64,140}, {1,1,1,1,1,1} /* special: repeated 1-frame chunks */
};

static void render_quantum(breaks_t *b, float *dst, unsigned partition)
{
    unsigned off=0, count=0;
    while (off<QUANTUM) {
        unsigned n;
        if (partition==4) n=1;
        else { n=partitions[partition][count++]; require(n!=0,"bad partition"); }
        require(n<=256 && off+n<=QUANTUM,"bad partition span");
        struct {uint32_t lo;float pcm[256];uint32_t hi;} guard;
        guard.lo=UINT32_C(0x1234bcde); guard.hi=UINT32_C(0xdebc4321);
        for (unsigned i=0;i<256;i++) guard.pcm[i]=NAN;
        breaks_render(b,guard.pcm,(int)n);
        require(guard.lo==UINT32_C(0x1234bcde)&&guard.hi==UINT32_C(0xdebc4321),"canary");
        for (unsigned i=n;i<256;i++) require(isnan(guard.pcm[i]),"wrote past requested chunk length");
        for (unsigned i=0;i<n;i++) require(isfinite(guard.pcm[i]) && fabsf(guard.pcm[i])<=2.f,"PCM bounds");
        /* IEEE negative zero is acoustically the same as zero. A dormant
         * voice can produce -0 until breaks_silent short-circuits to +0.
         * Canonicalize only zero signs; all nonzero PCM must match bitwise. */
        for (unsigned i=0;i<n;i++) dst[off+i]=(guard.pcm[i]==0.f)?0.f:guard.pcm[i];
        off+=n;
    }
}

static void playback(uint32_t n,unsigned seed,unsigned partition,float *dst)
{
    uint32_t r=UINT32_C(0x9937fcda)^n^(UINT32_C(0x9e3779b9)*seed);
    uint8_t *data_a=malloc((n+1u)/2u),*data_b=malloc((n+1u)/2u);
    breaks_t *b=calloc(1,sizeof(*b));
    require(data_a&&data_b&&b,"allocation");
    for (uint32_t i=0;i<(n+1u)/2u;i++) {data_a[i]=(uint8_t)rnd(&r);data_b[i]=(uint8_t)rnd(&r);}
    brk_loop_t a={.adpcm=data_a,.nsamples=n,.rate=22050,.bars=1};
    brk_loop_t c={.adpcm=data_b,.nsamples=n,.rate=22050,.bars=1};
    breaks_init(b);breaks_set_loop(b,0,&a);breaks_set_loop(b,1,&c);
    require(b->bank[0].valid&&b->bank[1].valid,"valid banks");
    breaks_set(b,BRK_LEVEL,127);breaks_set(b,BRK_COMPLEX,96);
    breaks_set(b,BRK_BCHANCE,100);breaks_set(b,BRK_R2,95);
    breaks_set(b,BRK_R4,100);breaks_set(b,BRK_ALEN,0);
    breaks_set(b,BRK_BLEN,0);
    float sp16=((float)n/16.f)/((seed&1u)?64.875f:256.125f);
    unsigned held=0;
    for (unsigned epoch=0;epoch<QUANTA;epoch++) {
        if (epoch==24) {
            for (int key=0;key<=10;key++) breaks_live(b,key,0);
            breaks_stop(b);breaks_set_quiet(b,1);
            reached_stop++;
        }
        if (epoch<24) {
            if (epoch%3u==0u) {unsigned down=(epoch/3u)&1u;breaks_live(b,8,(int)down);reached_reverse++;}
            if (epoch%5u==0u) {unsigned key=(epoch/5u)%8u;
                if (held<8u) breaks_live(b,(int)held,0);
                breaks_live(b,(int)key,1);held=key;reached_live++;
            }
            if (epoch%7u==0u) breaks_set(b,BRK_PITCH,(int)((epoch*9u+seed)%25u));
            if (epoch%11u==0u && epoch>0u) {
                breaks_set_loop(b,(int)((epoch/11u)&1u),((epoch/11u)&1u)?&c:&a);reached_bank++;
            }
            if (epoch%4u==0u) {
                if (epoch>0) sp16*=(epoch&4u)?1.125f:0.875f;
                breaks_step(b,(int)((epoch/4u)&15u),(int)(epoch/64u),sp16,1);
            }
        }
        render_quantum(b,dst+(size_t)epoch*QUANTUM,partition);
        if (epoch==QUANTA-1) require(breaks_silent(b),"STOP must finish silent");
    }
    free(b);free(data_a);free(data_b);
}

int main(int argc,char **argv)
{
    if (argc!=2) { fputs("usage: breaks_chunk_partition_property_test PCM_FILE\n",stderr);return 2; }
    FILE *fp=fopen(argv[1],"wb");
    if (!fp) {perror("PCM_FILE");return 3;}
    const uint32_t lengths[]={65,513,4097,176400,2116800};
    float *reference=calloc(NSAMPLES,sizeof(float)),*other=calloc(NSAMPLES,sizeof(float));
    require(reference&&other,"PCM allocation");
    for (unsigned i=0;i<sizeof(lengths)/sizeof(lengths[0]);i++) for(unsigned s=0;s<2;s++) {
        playback(lengths[i],s,0,reference);
        for (unsigned part=1;part<5;part++) {
            playback(lengths[i],s,part,other);
            if (memcmp(reference,other,NSAMPLES*sizeof(float))) {
                for(unsigned j=0;j<NSAMPLES;j++) if (memcmp(&reference[j],&other[j],sizeof(float))) {
                    fprintf(stderr,"FAIL chunk invariant n=%" PRIu32 " seed=%u mode=%u sample=%u %g vs %g\n",
                            lengths[i],s,part,j,(double)reference[j],(double)other[j]);
                    return 1;
                }
                return 1;
            }
        }
        require(fwrite(reference,sizeof(float),NSAMPLES,fp)==NSAMPLES,"write PCM");
        printf("n=%" PRIu32 " seed=%u partitions=5 exact=1 stopped=1\n",lengths[i],s);
    }
    require(reached_live>0&&reached_reverse>0&&reached_bank>0&&reached_stop>0,"coverage");
    printf("events: held=%" PRIu64 " reverse=%" PRIu64 " bank=%" PRIu64 " stop=%" PRIu64 "\n",
           reached_live,reached_reverse,reached_bank,reached_stop);
    free(reference);free(other);
    if (fclose(fp)) {perror("close PCM");return 3;}
    return 0;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""F02: after a commanded loader transition, wait_for must not attach to another keyboard.

No real MIDI ports are opened and nothing is written. Models the audited first-match
bug (evidence/f02-stage1/repro.py) and asserts the fail-closed newly-appeared rule.
Run from the repo root: python3 tests/install_f02_loader_bind_test.py
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))
import fm1_install as fi  # noqa: E402

fi.DELAY["hs"] = 0.01
fi.DELAY["retry"] = 0
failed = 0


def ok(cond, what):
    global failed
    print(f"{what:<72} {'ok' if cond else 'FAIL'}")
    failed += not cond


def identity_packet(text):
    body = bytearray(34)
    body[0:4] = b"\x00\x59\x11\x1b"
    raw = text.encode("latin-1")
    if len(raw) > 27:
        raise SystemExit("identity text does not fit the handshake")
    body[6:6 + len(raw)] = raw
    body[33] = ~sum(body[6:33]) & 255
    return b"\xF0" + fi.pack7(bytes(body)) + b"\xF7"


class Link:
    def __init__(self, name, text):
        self.name = name
        self.text = text
        self.closed = False
        self._given = False

    def send(self, _pkt):
        return True

    def read(self, _timeout):
        if self._given:
            return None
        self._given = True
        return identity_packet(self.text)

    def drain(self):
        return None

    def close(self):
        self.closed = True


class Backend:
    def __init__(self, devices):
        self.devices = dict(devices)

    def input_names(self):
        return list(self.devices)

    def output_names(self):
        return list(self.devices)

    def open(self, in_name, _out_name):
        return Link(in_name, self.devices[in_name])


def first_match_loader(backend):
    """Current pre-repair behaviour: first enumerated loader wins."""
    up = fi.Updater(backend)
    return up.find(lambda ident: ident.loader, only_port=False)


def main():
    # Other keyboard already in its update loader and enumerated first; selected SMK still running.
    backend = Backend({
        "Other OTA": "ota-FM-1_906",
        "Selected SMK": "SMK-37 Pro_900",
    })
    wrong = first_match_loader(backend)
    ok(wrong is not None and wrong.name == "Other OTA",
       "model: first-match would attach to the unrelated loader")
    if wrong:
        wrong.link.close()

    up = fi.Updater(backend)
    before = up.matching_ports(lambda i: i.loader)
    ok(before == ["Other OTA"], "snapshot before transition is the pre-existing loader only")

    # Selected keyboard has not entered the loader yet: fail closed (do not take the old one).
    none = up.wait_for(lambda i: i.loader, 0.05, before)
    ok(none is None, "wait_for: only a pre-existing loader -> timeout (noloader), not that port")

    # Selected keyboard appears as a new loader while the unrelated one remains.
    backend.devices["Selected SMK"] = "ota-SMK-37 Pro_900"
    got = up.wait_for(lambda i: i.loader, 0.05, before)
    ok(got is not None and got.name == "Selected SMK" and got.id.loader,
       "wait_for: accepts exactly the newly appeared loader, not Other OTA")
    if got:
        got.link.close()
    ok(up.returned_port == "Selected SMK", "returned_port records the accepted transition port")

    # Two newly appeared loaders: refuse to choose (names must match PORT_RE).
    backend2 = Backend({
        "Other OTA": "ota-FM-1_906",
        "Felucca New A": "ota-SMK-37 Pro_900",
        "Felucca New B": "ota-SMK-37 Elite_900",
    })
    up2 = fi.Updater(backend2)
    try:
        up2.wait_for(lambda i: i.loader, 0.05, ["Other OTA"])
        ok(False, "wait_for: two new loaders raise InstallError")
    except fi.InstallError as e:
        ok(e.code == "model" and "more than one new device" in str(e),
           "wait_for: two new loaders raise InstallError (fail closed)")

    # Post-write / slot-restore reconnect: do not hand another running keyboard.
    running = Backend({
        "Other SMK": "SMK-37 Pro_800",
        "Selected SMK": "SMK-37 Pro_900",
    })
    up3 = fi.Updater(running)
    up3.returned_port = "Selected SMK"
    back = up3.reconnect_after(lambda i: not i.loader, 0.05)
    ok(back is not None and back.name == "Selected SMK",
       "reconnect_after: reopens the transition port, not the sibling keyboard")
    if back:
        back.link.close()

    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Interrupt production SMC consumers when they release a full queue slot.

The injected callback models the ISR producer running immediately after the
consumer publishes its read index. Queue code and producers come from the
selected production source; MIDI/UI actions alone are recorded substitutes.
SMC_SOURCE selects an unchanged base for the negative control.
"""
import os
from pathlib import Path
import re
import shlex
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
SOURCE = Path(os.environ.get("SMC_SOURCE", ROOT / "firmware/src/app/smc_mixer.c"))
source = SOURCE.read_text()


def function(name):
    match = re.search(r"^[^\n]*\b" + name + r"\([^\n]*\)\s*\{", source, re.M)
    if not match:
        raise RuntimeError(f"Production function not found: {name}")
    depth, end = 1, match.end()
    while depth:
        if end == len(source):
            raise RuntimeError(f"Unterminated production function: {name}")
        depth += (source[end] == "{") - (source[end] == "}")
        end += 1
    return source[match.start():end]


prefix = source[source.index("#define SMC_Q"):source.index("int smc_project_active")]
poll = function("smc_poll")
for index, name in enumerate(("smc_qr", "smc_host_r", "smc_mmc_r[src]")):
    statement = re.escape(name) + r" = \(uint8_t\)\(r \+ 1u\);"
    poll, matches = re.subn(statement, lambda m: m[0] + f" interleave({index});", poll)
    if matches != 1:
        raise RuntimeError(f"Expected one production publication for {name}, got {matches}")

harness = r'''
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "app/smc_protocol.h"
#include "smc_fx_harness_stubs.h"
#define X0X_COLD
#define PROJ_BT_SMC_CENTRAL 16u
#define PROJ_BT_SMC_USER 32u
typedef struct { uint8_t kind, a, b, c; } pref_t;
enum { O_NONE, O_ASK, NKIT = 2 };
static struct { struct { uint8_t bt; } set; } proj;
static struct { uint8_t overlay, help; } ui;
static int locked, testing, inject, route, mmc_src, reset_on_first;
static unsigned count;
static uint8_t observed[64][7];
static int perf_testing(void) { return testing; }
static int ui_project_busy(void) { return locked; }
static void engine_smc_solo(int n) { (void)n; }
static void ui_say(const char *a, const char *b) { (void)a; (void)b; }
''' + prefix + "\n" + "\n".join(function(name) for name in
    ("smc_project_active", "smc_solo_clear") if "smc_solo_clear" in source) + "\n" + "\n".join(function(name) for name in (
    "smc_project_drop", "smc_ble_midi", "smc_midi_host", "smc_mmc_host")) + r'''

static void record(const uint8_t *m, uint8_t n)
{
    assert(count < 64 && n <= 6);
    observed[count][0] = n;
    memcpy(observed[count] + 1, m, n);
    count++;
    if (reset_on_first && count == 1) smc_project_drop();
}
static uint8_t smc_message(const uint8_t *m, uint8_t n, int allow)
{
    assert(allow);
    record(m, n);
    return 0;
}
static void smc_guarded_button(uint8_t note, int mmc, int allow)
{
    assert(mmc && allow);
    record(&note, 1);
}
static void enqueue(unsigned i)
{
    if (route == 0) {
        /* Mixed lengths expose a torn length/payload as well as lost messages. */
        const uint8_t msg[6] = {0xF0, 0x7F, 0x7F, 6, (uint8_t)(i + 1), 0xF7};
        if ((i & 1) || i == SMC_Q) {
            const uint8_t cc[3] = {0xB0, 16, (uint8_t)(i + 1)};
            smc_ble_midi(cc, 3);
        } else smc_ble_midi(msg, 6);
    } else if (route == 1) {
        uint32_t pkt = 0x0Bu | (0xBFu << 8) | (16u << 16) | ((i + 1u) << 24);
        assert(smc_midi_host(pkt));
    } else smc_mmc_host((uint8_t)(i + 1), (uint8_t)mmc_src);
}
static void interleave(int queue)
{
    if (!inject || queue != (route == 4 ? 2 : route)) return;
    inject = 0;
    if (route == 4) {
        smc_mmc_host(33, (uint8_t)mmc_src); /* ISR refills the released slot */
        smc_mmc_host(34, (uint8_t)mmc_src); /* STOP overflows after PLAY */
    } else enqueue(route == 2 ? 16 : SMC_Q);
